/* prerelease.js — the PRE-RELEASE RECORDS, once they are frozen.
 *
 * DATA ONLY. Nothing here has behaviour, because this is the one file in the
 * project that gets thrown away and rewritten wholesale: it is regenerated by
 * `PL.Archive.dump()` and pasted over. The screen that reads it is
 * src/archive.js, and that file is never regenerated.
 *
 * While `frozen` is false the archive screen follows the live shared board, so
 * it is always current and there is nothing to maintain. Freezing is one
 * deliberate step, and it is what makes the pre-release board outlive the
 * sheet:
 *
 *   1. Open the game with the shared board reachable and let it load.
 *   2. In the browser console:  copy(PL.Archive.dump())
 *   3. Paste over the whole of this file and commit it.
 *
 * After that the rows below ARE the archive. The sheet can be wiped, the
 * deployment deleted, config.js pointed somewhere else, and this screen still
 * reads exactly as it did the moment it was frozen.
 */
window.PL = window.PL || {};
window.PL.PreRelease = {
  frozen: false,
  capturedAt: '',
  rows: []
};
